// Keep the newest articles from each feed and clean up the fields.
const PER_FEED = 5;
const bySource = {};

$input.all().forEach((item, i) => {
  const e = item.json;
  if (!e.link || !e.title) return;
  let source = null;
  try { source = $('Get sources').itemMatching(i).json.id; } catch (err) {}
  const text = String(e.contentSnippet || e.content || '')
    .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 3000);
  (bySource[source] ??= []).push({
    url: e.link,
    title: e.title.trim(),
    content: text,
    published_at: e.isoDate || null,
    source,
    image_url: (e.enclosure && e.enclosure.url) || '',
  });
});

const articles = Object.values(bySource).flatMap(list =>
  list.sort((a, b) => String(b.published_at).localeCompare(String(a.published_at))).slice(0, PER_FEED));

return [{ json: { articles } }];

// Keep only articles Django doesn't have yet, and build the Ollama request for each.
const MODEL = 'qwen3:1.7b';
const CATEGORIES = ['world', 'politics', 'business', 'technology', 'science', 'health', 'sports', 'culture', 'central-asia', 'other'];

const articles = $('Keep newest').first().json.articles;
const fresh = new Set($json.new);

return articles.filter(a => fresh.has(a.url)).map(a => ({
  json: {
    article: a,
    ollama_body: {
      model: MODEL,
      stream: false,
      think: false,
      // A JSON schema forces the model to pick one of our categories.
      format: {
        type: 'object',
        properties: {
          summary: { type: 'string' },
          category: { type: 'string', enum: CATEGORIES },
          tags: { type: 'array', items: { type: 'string' } },
        },
        required: ['summary', 'category', 'tags'],
      },
      options: { temperature: 0.2, num_ctx: 2048 },
      prompt: `Summarize this news article for a news website.
Use ONLY facts stated in the text. Do not add opinions, predictions or background.
Return JSON with:
- "summary": 2-3 sentences in English
- "category": the best topic. Guide:
  central-asia: Turkmenistan, Kazakhstan, Kyrgyzstan, Tajikistan, Uzbekistan
  politics: governments, elections, officials, diplomacy
  health: medicine, vaccines, drugs, FDA
  technology: AI, software, gadgets, internet, tech companies
  business: companies, markets, economy, prices
  world: wars, disasters and other international events
  science, sports, culture: as named
  other: only if nothing else fits
- "tags": 3-5 short lowercase keywords

Title: ${a.title}
Text: ${a.content || a.title}`,
    },
  },
}));

// Merge the AI result into the article. If the model failed, save the article without a summary.
// The small model often misses Central Asia, so a keyword check overrides its category.
const CENTRAL_ASIA = /\b(turkmen\w*|ashgabat|kazakh\w*|astana|almaty|kyrgyz\w*|bishkek|tajik\w*|dushanbe|uzbek\w*|tashkent|samarkand|central asia\w*)\b/i;
const originals = $('Only new').all();

return $input.all().map((item, i) => {
  const article = { ...originals[i].json.article };
  let ai = {};
  try { ai = JSON.parse(item.json.response || '{}'); } catch (err) {}
  article.summary_en = typeof ai.summary === 'string' ? ai.summary.trim() : '';
  article.category = typeof ai.category === 'string' ? ai.category : 'other';
  article.tags = Array.isArray(ai.tags) ? ai.tags.filter(t => typeof t === 'string') : [];
  if (CENTRAL_ASIA.test(`${article.title} ${article.content}`)) article.category = 'central-asia';
  return { json: article };
});
